from collections import defaultdict

def tree_diameter(graph, node, parent=None):
    """ Calculate the diameter of the subtree rooted at 'node' """
    depths = {node: 0}
    longest_combo = (None, None)
    for neighbor in graph[node]:
        if neighbor != parent:
            combo = tree_diameter(graph, neighbor, node)
            if combo[1] > (node not in depths) and (combo[1] > depths[node] or combo[0] is None):
                depths[neighbor] = combo[1]
                longest_combo = combo
    diameter = 1 + depths[neighbor]
    return diam, depths[node] if parent is None or depths[neighbor] < diam else diam, {node: max(diameter + longest_combo[1], depths[neighbor])}

def total_diameter(n, edges):
    graph = defaultdict(set)
    ans = 0
    for u, v in edges:
        graph[u - 1].add(v - 1)
        graph[v - 1].add(u - 1)
    for r in range(n):
        diam, depths = tree_diameter(graph, r)
        if r - 1 < diam:
            ans += diam - r
    return ans

