        if victim_name in self.victims:
            raise ValueError(f"Duplicate victim name: {victim_name}")
        self.victims[victim_name] = suspicion_value

    def change_suspicions(self, victim_index, new_suspicions):
        self.suspicions[victim_index] = new_suspicions

    def find_max_suspicions(self, string):
        if not string:
            return 0
        suspicions = sorted([self.victims[li] for li in self.victims if li.startswith(string) or string in li], reverse=True)
