class DeathNoteDatabase:

    def __init__(self):
        self.victims = [[] for _ in range(26)]  # Track names of victims
        self.suspicion = [0] * 26           # Track suspicion values of victims
        self.next_position = [0] * 26       # Position of the next appearance of each letter
        self.sequences = {}                 # HashMap to store the maximum suspicion values of contiguous substrings

    def add_victim(self, victim_name):
        for name in victim_name:
            old_position = self.next_position[ord(name) - ord('a')]
            self.suspicion[old_position] = 0
            self.victims[ord(name) - ord('a')].pop()
        victim_name_tuple = tuple(sorted(victim_name))
        if victim_name_tuple not in self.sequences:
            self.sequences[victim_name_tuple] = 0
        for victim_name in victim_name:
            position = self.next_position[ord(victim_name[0]) - ord('a')]
            for i in range(1, len(victim_name)):
                self.next_position[ord(victim_name[i]) - ord('a')] = self.next_position[ord(victim_name[i-1]) - ord('a')]
                self.suspicion[self.next_position[ord(victim_name[i]) - ord('a')]] = 0
            self.victims[ord(victim_name[0]) - ord('a')].append((victim_name, self.sequences[victim_name_tuple]))
            self.sequences[victim_name_tuple] += 1

    def query(self, q_string):
        q_string_tuple = tuple(sorted(q_string))
        return self.sequences[q_string_tuple]

