    in_degrees = [0] * n
    for _ in range(n - 1):
        u, v = map(int, read().split())
        edges[u - 1].append(v - 1)
        edges[v - 1].append(u - 1)
        in_degrees[u - 1] += 1
        in_degrees[v - 1] += 1

    def dfs(node, prev, last_visit, time):
        for neighbor in edges[node]:
            if neighbor == prev:
                continue
            if in_degrees[neighbor] == 0:  # If not in the loop
                dfs(neighbor, node, last_visit, time + 1)
            else:
                dfs(neighbor, node, last_visit, time)
        nonlocal max_time
        current_time = time
        if max_time == 0 or current_time > max_time:
            max_time = current_time

    max_time = 0
    dfs(0, -1, 0, 0)

    route = []
    def backtrack(node, prev, current_time):
        nonlocal max_time
        if node == 0:
            if max_time == 0 or current_time > max_time:
                route.append((node + 1, current_time))
                return
        for neighbor in edges[node]:
            if neighbor == prev:
                continue
            backtrack(neighbor, node, min(max_time, current_time))
        route.append((node + 1, current_time))

