# Define a node for the suffix array and LA (Longest Alignment) tree
class Node:
    def __init__(self):
        self.children = defaultdict(Node)
        self.inserted = False

# Function to build the LA/SA tree
def build_sa_la(s):
    n = len(s)
    roots, sa = [Node() for _ in range(32)], [x for x in range(n)]
    for i in range(n - 1):
        roots[0].children[s[i]] = i
        for j in range(32):
            if i + (1 << j) < n and s[i + (1 << j)] == s[i + (1 << j + 1)]:
                sa[2 * i + 1 + j] = sa[2 * i + 1], roots[j]
                roots[j] = sa
            elif j:
                sa[2 * i + 1 + j] = sa[2 * i + 1 + (j - 1)]
        for j in range(32):
            if roots[j].inserted:
                sa[2 * i + 1 + j] = roots[j].index()
    return sa

# Function to find the longest common prefix between two strings
def lcp_prefix(s1, s2):
    n = min(len(s1), len(s2))
    for i in range(n):
        if s1[i] != s2[i]:
            return n - i
    return n

