from itertools import permutations

def dfs(index, path, memo):
    if index == n:
        return len(set(map(tuple, path)))

    if (index, tuple(path[::index])) in memo:
        return memo[index, tuple(path[::index])]

    max_length = 0
    used = False

    for j in range(index, n):
        if forbidden[j] and used:
            continue
        total_length = sum(k[j] for k in path) / index
        if index == n - 1:
            max_length = max(max_length, total_length)
        else:
            # Keep only the longest valid paths
            max_length = max(max_length, dfs(j + 1, path[:j] + [(j, k[j])], memo) + k[j])
            used = True

    memo[index, tuple(path[::index])] = max_length
    return max_length

